const body = $json.body ?? $json;
const product_id = body.product_id;
const requested_quantity = Number(body.requested_quantity);
const reorder_buffer = Number(body.reorder_buffer ?? 0);

if (!product_id || !Number.isInteger(requested_quantity) || requested_quantity <= 0) {
  throw new Error('Invalid request. Provide product_id and a positive integer requested_quantity.');
}
if (!Number.isInteger(reorder_buffer) || reorder_buffer < 0) {
  throw new Error('reorder_buffer must be a non-negative integer.');
}

return [{ json: { product_id: String(product_id), requested_quantity, reorder_buffer, request_id: body.request_id ?? null, requested_at: new Date().toISOString() } }];

const req = $('Validate Request').first().json;
const response = $json;
const rows = Array.isArray(response) ? response : (Array.isArray(response.body) ? response.body : (response.data ?? []));
if (!Array.isArray(rows) || rows.length === 0) {
  return [{ json: { ...req, found: false, error: 'Product not found in Supabase.', status: 'product_not_found', current_stock: null, shortage_quantity: null, reorder_recommendation: null } }];
}
const product = rows[0];
const current_stock = Number(product.stock_quantity ?? 0);
const available_after_request = current_stock - req.requested_quantity;
const shortage_quantity = Math.max(0, req.requested_quantity - current_stock);
const stock_sufficient = shortage_quantity === 0;
const recommended_reorder_quantity = shortage_quantity > 0 ? shortage_quantity + req.reorder_buffer : 0;
return [{ json: {
  ...req,
  found: true,
  product_id: product.product_id,
  product_name: product.product_name,
  brand: product.brand,
  model: product.model,
  current_stock,
  requested_quantity: req.requested_quantity,
  available_after_request: Math.max(0, available_after_request),
  shortage_quantity,
  stock_sufficient,
  status: stock_sufficient ? 'stock_available' : 'stock_shortage',
  reorder_recommendation: stock_sufficient ? null : {
    recommended_quantity: recommended_reorder_quantity,
    reason: `Requested ${req.requested_quantity}, but only ${current_stock} are in stock. Shortage: ${shortage_quantity}.`,
    supplier_id: product.primary_supplier_id ?? null
  },
  analyzed_at: new Date().toISOString()
} }];
